        return None

    # Handle percentage ranges like '7.7%-8.3%'
    if '%' in range_str:
        parts = range_str.replace('%', '').split('-')
        return (float(parts[0]), float(parts[1]))

    # Handle volume ranges like '100k-1m'
    parts = range_str.split('-')
    def parse_value(v):
        v = v.strip()
        if 'k' in v:
            return float(v.replace('k', '')) * 1000
        elif 'm' in v:
            return float(v.replace('m', '')) * 1000000
        else:
            return float(v)

    return (parse_value(parts[0]), parse_value(parts[1]))

